SELECT EXISTS(
               SELECT 1
               FROM information_schema.columns
               WHERE table_name = #{tableName}
                 AND column_name = #{columnName}
                 AND table_schema = 'public'
           )

SELECT EXISTS(
               SELECT 1
               FROM information_schema.tables
               WHERE table_schema = 'public'
                 AND table_name = #{tableName}
           )

mapper.insert:

CREATE TABLE "${table.tableName}" (
id SERIAL PRIMARY KEY,


         "${col.columnName}" ${col.type}


);

COMMENT ON TABLE "${table.tableName}" IS '${table.description}';


        COMMENT ON COLUMN "${table.tableName}"."${col.columnName}" IS '${col.description}'

update.foreach:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = '${tableName}' AND column_name = '${col.columnName}' AND table_schema = 'public') THEN
        EXECUTE 'ALTER TABLE "${tableName}" ALTER COLUMN "${col.columnName}" TYPE ${col.type} USING "${col.columnName}"::${col.type}';
    ELSE
        EXECUTE 'ALTER TABLE "${tableName}" ADD COLUMN "${col.columnName}" ${col.type}';
    END IF;
END $$;
